package main

import "fmt"

// Rectangle represents a rectangle shape
type Rectangle struct {
	Width  float64 // exported
	Height float64 // exported
	// TODO: add an unexported field 'area float64' to cache the area
}

// NewRectangle creates a new Rectangle
func NewRectangle(w, h float64) *Rectangle {
	return &Rectangle{Width: w, Height: h}
}

// Area returns the area of the rectangle
// TODO: cache the result in the unexported 'area' field
func (r *Rectangle) Area() float64 {
	return r.Width * r.Height
}

// Perimeter returns the perimeter of the rectangle
func (r *Rectangle) Perimeter() float64 {
	return 2 * (r.Width + r.Height)
}

func main() {
	rect := NewRectangle(5, 3)
	fmt.Printf("Area: %.1f\n", rect.Area())
	fmt.Printf("Perimeter: %.1f\n", rect.Perimeter())
}
